/* Français — plantes */
I18N.fr.herbs = {
  nigella: { name: "Nigelle (graine noire, habba sawda)", part: "Graines et huile", uses: "Soutien immunitaire, asthme et allergies, toux, indigestion et gaz, aide à baisser la glycémie, la tension et le cholestérol ; affections cutanées en application.", prep: "Moudre les graines et les mélanger au miel, ou les consommer avec le pain et les plats, ou prendre l'huile. En externe : appliquer l'huile sur la peau.", dose: "Graines : 1 à 2 g par jour (½ cuillère à café). Huile : 1 cuillère à café (5 ml) par jour en plusieurs prises.", kids: "Après 2 ans : un quart de la dose avec du miel (après 1 an) ou dans les aliments.", caution: "Peut trop baisser la glycémie et la tension avec les médicaments du diabète et de l'hypertension. Arrêter 2 semaines avant une chirurgie. Peut provoquer une allergie cutanée en application." },
  honey: { name: "Miel naturel", part: "Produit de la ruche", uses: "Toux (prouvé chez l'enfant de plus d'1 an), mal de gorge, petites plaies et brûlures (miel médical), énergie, laxatif doux.", prep: "Dissoudre dans de l'eau tiède (non bouillante) ou consommer tel quel ; associer au citron, au gingembre et à la nigelle.", dose: "1 à 2 cuillères à soupe par jour.", kids: "⚠️ Strictement interdit avant 1 an (risque de botulisme infantile). Après 1 an : ½ à 1 cuillère à café au coucher contre la toux.", caution: "Augmente la glycémie — prudence en cas de diabète. Allergie rare chez les personnes allergiques au pollen." },
  ginger: { name: "Gingembre", part: "Rhizome", uses: "Nausées (grossesse, mal des transports, post-opératoires), indigestion, rhume, règles douloureuses, douleurs articulaires.", prep: "Tisane : 1 à 2 g de racine fraîche râpée dans une tasse d'eau bouillante 10 minutes. Ou en poudre avec du miel.", dose: "1 à 3 g sec par jour (jusqu'à 4 g). Grossesse : pas plus de 1 g par jour et sur une courte durée.", kids: "Après 2 ans : petites quantités en tisane diluée.", caution: "Peut augmenter le saignement avec les anticoagulants (warfarine, aspirine). Prudence en cas de calculs biliaires. À forte dose, brûlures d'estomac." },
  garlic: { name: "Ail", part: "Gousses", uses: "Baisse légère de la tension et du cholestérol, antimicrobien, rhume, soutien immunitaire, mycoses en application.", prep: "Écraser une gousse, attendre 10 minutes puis la consommer avec du miel ou des aliments (une longue cuisson réduit son effet).", dose: "1 à 2 gousses fraîches par jour (2 à 5 g), ou 600 à 1200 mg de poudre d'ail standardisée.", kids: "Quantités alimentaires uniquement.", caution: "Augmente le risque de saignement avec les anticoagulants ; arrêter une semaine avant une chirurgie. Interagit avec certains traitements du VIH. L'ail cru laissé sur la peau provoque des brûlures." },
  turmeric: { name: "Curcuma", part: "Rhizome", uses: "Anti-inflammatoire pour les douleurs articulaires et l'arthrose, indigestion, soutien du foie, plaies en application, « lait d'or » pour l'immunité.", prep: "À prendre avec du poivre noir et un corps gras (lait ou huile) pour mieux l'absorber. Lait d'or : ½ cuillère à café de curcuma + une pincée de poivre dans une tasse de lait chaud.", dose: "Poudre : 1 à 3 g par jour. Extrait de curcumine : 500 mg deux fois par jour.", kids: "Quantités alimentaires uniquement.", caution: "À éviter en cas de calculs biliaires ou d'obstruction des voies biliaires et avec les anticoagulants. Rares atteintes du foie signalées avec les compléments concentrés." },
  cinnamon: { name: "Cannelle", part: "Écorce", uses: "Indigestion et gaz, aide à contrôler la glycémie, rhume, règles douloureuses.", prep: "Faire bouillir un bâton de cannelle dans une tasse d'eau 10 minutes, ou ajouter la poudre aux aliments.", dose: "1 à 2 g par jour (½ cuillère à café). Préférer la cannelle de Ceylan.", kids: "Quantités alimentaires.", caution: "La cannelle casse (chinoise, courante) est riche en coumarine, toxique pour le foie à forte dose. Peut baisser la glycémie avec les antidiabétiques." },
  chamomile: { name: "Camomille", part: "Fleurs", uses: "Anxiété légère et insomnie, crampes d'estomac et gaz, irritations de la peau et de la bouche en application, irritation légère des yeux (compresses), règles douloureuses.", prep: "2 à 3 g (1 cuillère à soupe) de fleurs dans 150 ml d'eau bouillante, couvert, 5 à 10 minutes.", dose: "3 à 4 tasses par jour.", kids: "Tisane diluée pour les coliques après 6 mois, en petites quantités.", caution: "Allergie chez les personnes allergiques aux Astéracées (ambroisie, chrysanthème). Peut interagir avec la warfarine et les sédatifs." },
  peppermint: { name: "Menthe poivrée", part: "Feuilles et huile", uses: "Syndrome de l'intestin irritable (capsules d'huile — prouvé), gaz et ballonnements, céphalée de tension (huile sur le front), nausées, nez bouché.", prep: "Tisane : 1,5 à 3 g de feuilles dans une tasse d'eau bouillante 10 minutes.", dose: "Tisane 3 fois par jour. Capsules gastro-résistantes d'huile 0,2 ml (environ 180 mg) 2 à 3 fois par jour avant les repas pour le côlon irritable.", kids: "⚠️ Jamais d'huile ni de menthol près du visage des bébés et des enfants de moins de 3 ans (arrêt respiratoire possible). Tisane diluée après 4 ans.", caution: "Aggrave les brûlures d'estomac et le reflux. À éviter en cas de calculs biliaires." },
  mint: { name: "Menthe verte (nanaa)", part: "Feuilles", uses: "Indigestion, gaz et nausées, mauvaise haleine. Des études suggèrent qu'elle pourrait réduire la pilosité excessive en cas de SOPK.", prep: "Feuilles fraîches dans le thé (atay marocain) ou en infusion seule.", dose: "2 à 3 tasses par jour.", kids: "Tisane légère après 2 ans.", caution: "Peut aggraver le reflux acide." },
  thyme: { name: "Thym (zaâtar)", part: "Feuilles et sommités fleuries", uses: "Toux et bronchite (expectorant et antispasmodique), mal de gorge (gargarisme), gaz, antimicrobien.", prep: "1 à 2 g (1 cuillère à café) dans une tasse d'eau bouillante 10 minutes, sucré au miel. Gargarisme : infusion plus forte.", dose: "1 tasse 3 fois par jour.", kids: "Après 4 ans : ½ tasse deux fois par jour.", caution: "Allergie chez les personnes sensibles aux Lamiacées. L'huile concentrée ne doit pas être avalée." },
  sage: { name: "Sauge (salmia)", part: "Feuilles", uses: "Mal de gorge, inflammation de la bouche et des gencives (gargarisme), bouffées de chaleur et transpiration excessive de la ménopause, indigestion et crampes.", prep: "1 à 3 g dans une tasse d'eau bouillante 10 minutes.", dose: "Jusqu'à 3 tasses par jour, sur de courtes périodes (pas plus de 4 semaines d'affilée).", kids: "Gargarisme uniquement, après 6 ans.", caution: "Contient de la thuyone — à forte dose ou au long cours, risque de convulsions. À éviter en cas d'épilepsie. Diminue la production de lait." },
  rosemary: { name: "Romarin (azir)", part: "Feuilles et huile", uses: "Indigestion, circulation et mémoire, chute de cheveux (huile en application), douleurs musculaires et articulaires en application.", prep: "Tisane : 1 cuillère à café (2 g) dans une tasse d'eau bouillante 10 minutes.", dose: "2 à 4 g par jour en tisane.", kids: "Quantités alimentaires.", caution: "Éviter les fortes doses et l'huile concentrée en cas d'épilepsie. De grandes quantités peuvent augmenter la tension." },
  fennel: { name: "Fenouil", part: "Graines", uses: "Gaz, ballonnements et coliques, indigestion, toux, règles douloureuses, traditionnellement pour augmenter le lait maternel.", prep: "1 à 3 g de graines écrasées dans une tasse d'eau bouillante 10 à 15 minutes.", dose: "2 à 3 tasses par jour.", kids: "L'Agence européenne des médicaments déconseille la tisane de fenouil avant 4 ans sans avis médical.", caution: "Allergie chez les personnes allergiques au céleri et à la carotte. Effet œstrogénique — prudence en cas de tumeur hormonodépendante." },
  anise: { name: "Anis vert", part: "Graines", uses: "Gaz et coliques, toux et expectoration, insomnie légère, mauvaise haleine.", prep: "1 à 3 g de graines écrasées dans une tasse d'eau bouillante 10 minutes.", dose: "Jusqu'à 3 tasses par jour.", kids: "Tisane diluée après 2 ans. ⚠️ Ne pas confondre avec la badiane du Japon, toxique, surtout pour les bébés.", caution: "Allergie possible. Léger effet œstrogénique." },
  fenugreek: { name: "Fenugrec (halba)", part: "Graines", uses: "Aide à baisser la glycémie, augmente le lait maternel, ouvre l'appétit, constipation, toux, furoncles en cataplasme.", prep: "Faire tremper 1 cuillère à café de graines dans l'eau toute la nuit et boire, ou faire bouillir 5 à 10 minutes. En externe : pâte de poudre.", dose: "5 à 10 g de graines par jour.", kids: "Quantités alimentaires.", caution: "Baisse la glycémie — prudence avec les antidiabétiques. Fluidifie le sang. Allergie croisée avec l'arachide et le pois chiche. Donne une odeur à la sueur et aux urines." },
  cumin: { name: "Cumin", part: "Graines", uses: "Gaz et ballonnements, coliques, indigestion, diarrhée légère, côlon irritable.", prep: "1 cuillère à café de cumin dans une tasse d'eau bouillante 10 minutes après le repas, ou avec du citron.", dose: "1 à 3 g par jour.", kids: "Eau de cumin diluée après 1 an.", caution: "Peut baisser la glycémie. Sans danger en quantité alimentaire." },
  licorice: { name: "Réglisse", part: "Racine", uses: "Mal de gorge et toux, gastrite et ulcère de l'estomac, brûlures d'estomac.", prep: "Faire macérer la racine dans l'eau froide plusieurs heures (boisson de réglisse), ou faire bouillir 1 à 2 g.", dose: "1 à 5 g de racine par jour, pas plus de 4 à 6 semaines. La forme DGL (déglycyrrhizinée) est plus sûre pour l'estomac.", kids: "Usage médicinal déconseillé chez l'enfant.", caution: "⚠️ Augmente la tension, fait baisser le potassium et retenir l'eau. Interdite en cas d'hypertension, de maladie cardiaque ou rénale, et avec les diurétiques, la digoxine et les corticoïdes." },
  marjoram: { name: "Marjolaine (merdedouch)", part: "Feuilles", uses: "Régulation des règles et douleurs menstruelles, indigestion, anxiété légère, rhume.", prep: "1 cuillère à café dans une tasse d'eau bouillante 10 minutes.", dose: "1 à 2 tasses par jour.", kids: "Quantités alimentaires.", caution: "Peut agir sur les hormones. À éviter avant une chirurgie." },
  lavender: { name: "Lavande", part: "Fleurs et huile", uses: "Anxiété et stress, insomnie, maux de tête (inhalation ou application diluée), petites brûlures et piqûres d'insectes en application.", prep: "Tisane : 1 à 2 cuillères à café de fleurs dans une tasse d'eau bouillante. Un extrait d'huile oral standardisé (Silexan) existe dans certains pays.", dose: "Tisane 1 à 3 tasses par jour. Silexan : 80 mg par jour contre l'anxiété.", kids: "Inhalation légère après 3 ans. L'huile ne s'avale pas.", caution: "Peut renforcer l'effet des sédatifs. Effets hormonaux signalés chez des garçons avec des applications répétées." },
  lemon_balm: { name: "Mélisse", part: "Feuilles", uses: "Anxiété et stress, insomnie, troubles digestifs nerveux, bouton de fièvre (herpès) en application.", prep: "1,5 à 4,5 g dans une tasse d'eau bouillante 10 minutes.", dose: "2 à 3 tasses par jour.", kids: "Tisane diluée après 6 ans.", caution: "Peut interagir avec les médicaments de la thyroïde et les sédatifs." },
  valerian: { name: "Valériane", part: "Racine", uses: "Insomnie et difficultés d'endormissement, anxiété et tension nerveuse.", prep: "Tisane : 2 à 3 g de racine dans une tasse d'eau bouillante, ou extrait.", dose: "Extrait 300 à 600 mg 30 à 60 minutes avant le coucher. Effet après 2 à 4 semaines.", kids: "Pas avant 12 ans sans avis.", caution: "Ne pas associer à l'alcool, aux somnifères ou sédatifs. Somnolence matinale possible — éviter la conduite. Rares atteintes du foie." },
  ginseng: { name: "Ginseng asiatique", part: "Racine", uses: "Fatigue et épuisement, concentration, troubles de l'érection (preuves modérées), soutien immunitaire.", prep: "Faire bouillir la racine ou prendre un extrait standardisé.", dose: "200 à 400 mg d'extrait ou 1 à 2 g de racine par jour, en cures (3 semaines, puis 1 semaine de pause).", kids: "Pas chez l'enfant.", caution: "À éviter en cas d'hypertension non contrôlée et d'insomnie. Interagit avec la warfarine, les antidiabétiques et les antidépresseurs." },
  astragalus: { name: "Astragale (Huang qi)", part: "Racine", uses: "Soutien immunitaire et prévention des rhumes à répétition, fatigue générale.", prep: "Faire bouillir la racine 20 à 30 minutes (soupe ou décoction).", dose: "2 à 6 g de racine sèche par jour (davantage en médecine chinoise sous suivi d'un praticien).", kids: "Sur avis d'un professionnel.", caution: "À éviter en cas de maladie auto-immune et avec les immunosuppresseurs (après greffe)." },
  ashwagandha: { name: "Ashwagandha (ginseng indien)", part: "Racine", uses: "Stress et anxiété, insomnie, épuisement, force physique et fertilité masculine.", prep: "Poudre dans du lait chaud avec du miel, ou gélules d'extrait.", dose: "300 à 600 mg d'extrait de racine par jour.", kids: "Pas chez l'enfant.", caution: "⚠️ Cas d'atteinte du foie signalés. À éviter en cas d'hyperthyroïdie, de maladie auto-immune et avec les sédatifs. Interdite pendant la grossesse." },
  tulsi: { name: "Basilic sacré (Tulsi)", part: "Feuilles", uses: "Stress, rhume et toux, aide à contrôler la glycémie.", prep: "1 à 2 cuillères à café de feuilles sèches dans une tasse d'eau bouillante.", dose: "2 à 3 tasses par jour.", kids: "Tisane diluée.", caution: "Peut baisser la glycémie et fluidifier le sang. À éviter en cas de projet de grossesse." },
  triphala: { name: "Triphala (trois myrobolans)", part: "Fruits de trois plantes (amla, haritaki, bibhitaki)", uses: "Constipation et régulation intestinale, nettoyage digestif, santé bucco-dentaire (gargarisme).", prep: "Poudre dans de l'eau tiède au coucher.", dose: "3 à 5 g de poudre (1 cuillère à café) ou 500 à 1000 mg en comprimés au coucher.", kids: "Sur avis d'un professionnel.", caution: "Peut provoquer diarrhée et crampes. À éviter en cas de diarrhée. Acheter auprès d'une source fiable (risque de métaux lourds)." },
  neem: { name: "Neem (margousier)", part: "Feuilles et huile", uses: "En externe : acné, poux, mycoses, gale. Les brindilles de neem servent à nettoyer les dents.", prep: "Lotion de feuilles bouillies, ou huile diluée en application.", dose: "L'usage externe est le plus sûr.", kids: "⚠️ L'huile de neem est interdite par voie orale chez l'enfant (intoxication grave, parfois mortelle).", caution: "Par voie orale, peut nuire au foie et aux reins et diminuer la fertilité. À éviter en cas de projet de grossesse." },
  ginkgo: { name: "Ginkgo", part: "Feuilles (extrait standardisé)", uses: "Troubles de la mémoire et de la concentration chez la personne âgée, acouphènes, vertiges, mauvaise circulation périphérique.", prep: "Uniquement en extrait standardisé (EGb 761).", dose: "120 à 240 mg par jour en deux prises ; évaluer après 6 à 8 semaines.", kids: "Pas chez l'enfant.", caution: "⚠️ Augmente le risque de saignement avec les anticoagulants et l'aspirine. Arrêter avant une chirurgie. Les graines crues sont toxiques. À éviter en cas d'épilepsie." },
  echinacea: { name: "Échinacée", part: "Parties aériennes et racine", uses: "Pourrait raccourcir un rhume si prise dès les premiers symptômes (preuves modestes).", prep: "Extrait, teinture ou tisane.", dose: "300 à 500 mg d'extrait 3 fois par jour, pas plus de 10 jours.", kids: "Déconseillée avant 12 ans (risque d'éruption allergique).", caution: "Allergie chez les personnes sensibles aux Astéracées. À éviter en cas de maladie auto-immune." },
  elderberry: { name: "Sureau noir", part: "Baies cuites et fleurs", uses: "Grippe et rhume (pourrait raccourcir la durée).", prep: "Sirop de baies cuites ou infusion de fleurs.", dose: "Sirop standardisé 15 ml 4 fois par jour pendant 3 à 5 jours.", kids: "Uniquement produits standardisés pour enfants.", caution: "⚠️ Les baies crues, les feuilles et les tiges sont toxiques (vomissements, diarrhée) — à cuire obligatoirement." },
  st_johns_wort: { name: "Millepertuis", part: "Sommités fleuries", uses: "Dépression légère à modérée (bonnes preuves) ; huile rouge pour plaies et brûlures en application.", prep: "Extrait standardisé (0,3 % d'hypericine).", dose: "300 mg 3 fois par jour.", kids: "Pas sans suivi médical.", caution: "⚠️⚠️ Interactions médicamenteuses très graves : rend inefficaces la pilule, la warfarine, les médicaments du cœur (digoxine), du VIH et des greffes. Avec les antidépresseurs : syndrome sérotoninergique. Augmente la sensibilité au soleil." },
  milk_thistle: { name: "Chardon-Marie", part: "Graines", uses: "Soutien du foie (stéatose, hépatite chronique) — preuves partagées. Indigestion.", prep: "Extrait standardisé (silymarine).", dose: "Silymarine 140 mg 2 à 3 fois par jour.", kids: "Sur avis médical.", caution: "Allergie aux Astéracées. Peut baisser la glycémie. Diarrhée légère." },
  dandelion: { name: "Pissenlit", part: "Feuilles et racine", uses: "Diurétique (feuilles), indigestion et stimulation de la bile (racine), appétit.", prep: "Feuilles fraîches en salade, ou 4 à 10 g dans une tasse d'eau bouillante.", dose: "3 tasses par jour.", kids: "Quantités alimentaires.", caution: "À éviter en cas d'obstruction des voies biliaires, avec le lithium et les diurétiques. Allergie aux Astéracées." },
  nettle: { name: "Ortie", part: "Feuilles et racine", uses: "Feuilles : douleurs articulaires, allergies saisonnières, diurétique, anémie (riche en minéraux). Racine : hypertrophie bénigne de la prostate.", prep: "2 à 4 g de feuilles sèches dans une tasse d'eau bouillante.", dose: "Feuilles : 3 tasses par jour. Extrait de racine : 120 à 360 mg par jour.", kids: "Quantités alimentaires (cuite).", caution: "Peut baisser la tension et la glycémie. Interagit avec les diurétiques, le lithium et la warfarine (riche en vitamine K)." },
  hibiscus: { name: "Hibiscus (bissap, karkadé)", part: "Calice", uses: "Baisse l'hypertension légère (bonnes preuves), cholestérol, diurétique, boisson rafraîchissante.", prep: "1,5 à 2 g (1 cuillère à café) dans une tasse d'eau bouillante, ou en infusion froide.", dose: "2 à 3 tasses par jour.", kids: "Boisson légère en quantité modérée.", caution: "Peut trop baisser la tension avec les antihypertenseurs. Interagit avec l'hydrochlorothiazide et certains médicaments." },
  senna: { name: "Séné", part: "Feuilles et gousses", uses: "Constipation occasionnelle (laxatif stimulant puissant).", prep: "Infuser 0,5 à 2 g dans de l'eau chaude 10 minutes, boire le soir. Agit en 6 à 12 heures.", dose: "L'équivalent de 15 à 30 mg de sennosides au coucher, pas plus de 1 à 2 semaines.", kids: "⚠️ Pas avant 12 ans sans médecin.", caution: "L'usage prolongé fait perdre du potassium et rend l'intestin dépendant. Interdit en cas d'occlusion, de douleur abdominale inexpliquée, d'appendicite et de maladie inflammatoire de l'intestin." },
  psyllium: { name: "Psyllium (ispaghul)", part: "Téguments des graines", uses: "Constipation chronique, diarrhée légère (régule la consistance), côlon irritable, hémorroïdes, baisse du cholestérol.", prep: "Mélanger dans un grand verre (250 ml) d'eau ou de jus et boire aussitôt, puis un autre verre d'eau.", dose: "5 à 10 g (1 à 2 cuillères à café) 1 à 3 fois par jour.", kids: "6 à 12 ans : moitié de la dose adulte.", caution: "Boire suffisamment (risque d'obstruction et d'étouffement). À prendre 2 heures à distance des médicaments. Interdit en cas de troubles de la déglutition ou d'occlusion." },
  flaxseed: { name: "Graines de lin", part: "Graines", uses: "Constipation, baisse du cholestérol, source végétale d'oméga-3, symptômes légers de la ménopause.", prep: "Moudre fraîchement et ajouter au yaourt, à l'eau ou au jus.", dose: "1 à 2 cuillères à soupe moulues (10 à 20 g) par jour avec un verre d'eau.", kids: "Petites quantités dans les aliments.", caution: "Boire suffisamment. À prendre 2 heures à distance des médicaments. Les graines immatures sont toxiques." },
  clove: { name: "Clou de girofle", part: "Boutons floraux et huile", uses: "Mal de dents (en application), gaz et indigestion, mauvaise haleine.", prep: "Placer un clou sur la dent douloureuse, ou 1 à 2 clous dans le thé.", dose: "Tisane : 1 à 2 clous par tasse. Huile en application, diluée uniquement.", kids: "⚠️ L'huile de girofle est interdite par voie orale chez l'enfant (toxique pour le foie).", caution: "Fluidifie le sang. L'huile pure irrite les gencives." },
  cardamom: { name: "Cardamome", part: "Graines", uses: "Indigestion, gaz et nausées, mauvaise haleine, appétit.", prep: "Deux gousses écrasées dans le café, le thé ou l'eau bouillante.", dose: "Jusqu'à 1,5 g par jour.", kids: "Quantités alimentaires.", caution: "Éviter les doses médicinales en cas de calculs biliaires." },
  saffron: { name: "Safran", part: "Stigmates de la fleur", uses: "Dépression légère (preuves relativement bonnes), syndrome prémenstruel, humeur.", prep: "Quelques filaments infusés dans de l'eau tiède ou du lait.", dose: "30 mg par jour (environ 10 à 15 filaments). Ne pas dépasser 1,5 g. Plus de 5 g est toxique.", kids: "Quantités alimentaires.", caution: "⚠️ À forte dose, risque de fausse couche et de saignement. Attention au safran falsifié." },
  moringa: { name: "Moringa", part: "Feuilles", uses: "Complément nutritionnel riche en fer, protéines et vitamines, malnutrition, aide au contrôle de la glycémie.", prep: "Poudre de feuilles dans les aliments, les jus ou en tisane.", dose: "2 à 6 g (1 à 2 cuillères à café) de poudre de feuilles par jour.", kids: "Poudre de feuilles dans les aliments en petites quantités.", caution: "Racine et écorce interdites pendant la grossesse (risque de fausse couche). Peut baisser la glycémie et interagir avec les médicaments de la thyroïde." },
  aloe: { name: "Aloe vera", part: "Gel interne", uses: "En externe : petites brûlures et coups de soleil, plaies superficielles, peau sèche, psoriasis léger.", prep: "Fendre la feuille et appliquer le gel transparent sur la peau.", dose: "En application 2 à 3 fois par jour.", kids: "Le gel en application est généralement sans danger.", caution: "⚠️ La sève jaune (latex) est un laxatif puissant à ne pas boire (retirée des médicaments aux États-Unis). Boire de l'aloe peut baisser le potassium et la glycémie." },
  shih: { name: "Armoise blanche (chih)", part: "Parties aériennes", uses: "Indigestion, crampes et gaz, vers intestinaux traditionnellement, ajoutée au thé en hiver. Utilisée en médecine populaire pour la glycémie.", prep: "Un petit brin dans l'atay ou une infusion légère.", dose: "Petites quantités sur de courtes périodes (1 tasse par jour pendant quelques jours).", kids: "Pas chez l'enfant.", caution: "⚠️ Contient de la thuyone — de fortes doses ou un usage prolongé provoquent convulsions et atteintes nerveuses. Interdite en cas d'épilepsie." },
  myrrh: { name: "Myrrhe", part: "Résine", uses: "Aphtes et inflammation des gencives (bain de bouche), mal de gorge, plaies en application.", prep: "Quelques gouttes de teinture de myrrhe dans un verre d'eau en bain de bouche.", dose: "Rincer 2 à 3 fois par jour. Usage interne déconseillé sans professionnel.", kids: "Bain de bouche après 6 ans, sans avaler.", caution: "Peut baisser la glycémie. De fortes doses internes irritent les reins." },
  frankincense: { name: "Encens (oliban, Boswellia)", part: "Résine", uses: "Douleurs articulaires et arthrose (l'extrait de boswellia est étudié), asthme traditionnellement ; mâché pour la mémoire et la digestion dans la tradition arabe.", prep: "Faire tremper l'encens dans l'eau une nuit et boire, ou le mâcher, ou prendre un extrait standardisé.", dose: "Extrait de boswellia 300 à 500 mg 2 à 3 fois par jour.", kids: "Mâcher un petit morceau.", caution: "Troubles digestifs légers. Peut interagir avec les anticoagulants." },
  costus: { name: "Costus indien (qist al-hindi)", part: "Racine", uses: "Cité dans la tradition pour la toux, le mal de gorge, le rhume et les amygdales (inhalé ou léché avec du miel), et en application pour la peau.", prep: "Mélanger la poudre au miel ou à l'huile.", dose: "Traditionnellement ¼ à ½ cuillère à café par jour sur une courte durée. Preuves scientifiques limitées.", kids: "Déconseillé chez l'enfant.", caution: "⚠️ Risque de falsification avec des plantes contenant de l'acide aristolochique, cancérogène et toxique pour les reins. N'acheter qu'auprès d'une source fiable et contrôlée." },
  garden_cress: { name: "Cresson alénois (hab al-rachad)", part: "Graines", uses: "Toux et asthme traditionnellement, production de lait, anémie (riche en fer), fractures traditionnellement.", prep: "Faire tremper 1 cuillère à café dans l'eau ou le lait jusqu'à consistance gélatineuse.", dose: "1 cuillère à café par jour.", kids: "Petites quantités dans les aliments.", caution: "⚠️ Stimule l'utérus — interdit pendant la grossesse. De grandes quantités peuvent agir sur la thyroïde." },
  talbina: { name: "Talbina (bouillie d'orge)", part: "Farine d'orge complète", uses: "Décrite comme « réconfortant le cœur du malade et dissipant une part de la tristesse ». Riche en bêta-glucane : baisse le cholestérol, régule le transit, nourrissante en convalescence.", prep: "Cuire 1 à 2 cuillères à soupe de farine d'orge dans une tasse de lait ou d'eau à feu doux 10 à 15 minutes ; sucrer au miel.", dose: "Un repas par jour.", kids: "Aliment adapté après 6 mois (pas de miel avant 1 an).", caution: "Contient du gluten — interdite en cas de maladie cœliaque." },
  cranberry: { name: "Canneberge (cranberry)", part: "Baies", uses: "Prévention des infections urinaires à répétition (ne traite pas une infection en cours).", prep: "Jus non sucré ou gélules standardisées.", dose: "250 à 500 ml de jus par jour, ou extrait à 36 mg de PAC.", kids: "Jus en quantité modérée.", caution: "Peut interagir avec la warfarine. Prudence en cas de calculs d'oxalate." },
  saw_palmetto: { name: "Palmier nain (saw palmetto)", part: "Baies", uses: "Symptômes de l'hypertrophie bénigne de la prostate (preuves récentes partagées), alopécie masculine (preuves faibles).", prep: "Extrait lipidique standardisé.", dose: "320 mg par jour.", kids: "Non utilisé.", caution: "Troubles digestifs. Peut interagir avec les traitements hormonaux et les anticoagulants." },
  black_cohosh: { name: "Actée à grappes noires (cimicifuga)", part: "Racine", uses: "Bouffées de chaleur et symptômes de la ménopause.", prep: "Extrait standardisé.", dose: "20 à 40 mg d'extrait deux fois par jour, pas plus de 6 mois.", kids: "Non utilisé.", caution: "⚠️ Rares atteintes du foie — arrêter en cas de jaunisse ou d'urines foncées. À éviter en cas de maladie du foie et de cancer du sein." },
  vitex: { name: "Gattilier (Vitex)", part: "Baies", uses: "Syndrome prémenstruel (douleur des seins, sautes d'humeur), légères irrégularités du cycle.", prep: "Extrait standardisé le matin.", dose: "20 à 40 mg d'extrait par jour pendant au moins 3 mois.", kids: "Pas avant la puberté.", caution: "Interagit avec la pilule, les traitements hormonaux et les médicaments dopaminergiques (Parkinson, antipsychotiques)." },
  green_tea: { name: "Thé vert", part: "Feuilles", uses: "Antioxydant, vigilance, aide pour le poids et le cholestérol.", prep: "1 cuillère à café dans de l'eau à 80 °C pendant 2 à 3 minutes.", dose: "3 à 5 tasses par jour.", kids: "Contient de la caféine — petites quantités.", caution: "⚠️ Les compléments d'extrait concentré de thé vert ont causé des atteintes du foie. Réduit l'absorption du fer (à boire à distance des repas). La caféine provoque insomnie et palpitations." },
  willow_bark: { name: "Écorce de saule blanc", part: "Écorce", uses: "Mal de dos, douleurs articulaires et maux de tête (source de salicine, origine de l'aspirine).", prep: "Décoction d'écorce ou extrait.", dose: "Extrait équivalent à 120 à 240 mg de salicine par jour.", kids: "⚠️ Interdite chez l'enfant et l'adolescent (risque de syndrome de Reye).", caution: "Interdite en cas d'allergie à l'aspirine, d'ulcère de l'estomac, avec les anticoagulants ou les anti-inflammatoires." },
  devils_claw: { name: "Griffe du diable (harpagophytum)", part: "Racines secondaires", uses: "Lombalgie, arthrose, douleurs articulaires.", prep: "Extrait standardisé.", dose: "Extrait équivalent à 50 à 100 mg d'harpagoside par jour.", kids: "Non utilisée.", caution: "À éviter en cas d'ulcère de l'estomac et de calculs biliaires. Peut interagir avec les anticoagulants, les antidiabétiques et les antihypertenseurs." },
  calendula: { name: "Souci (calendula)", part: "Fleurs", uses: "En externe : petites plaies, inflammations de la peau, érythème fessier, crevasses du mamelon. Gargarisme pour la bouche.", prep: "Pommade à 2 à 5 %, ou infusion de 1 à 2 g pour gargarismes et compresses.", dose: "En application 3 à 4 fois par jour.", kids: "Pommade généralement sans danger pour l'érythème fessier.", caution: "Allergie chez les personnes sensibles aux Astéracées." },
  olive_leaf: { name: "Feuille d'olivier", part: "Feuilles", uses: "Aide à baisser légèrement la tension et la glycémie, antioxydant.", prep: "1 cuillère à café de feuilles sèches dans une tasse d'eau bouillante 10 à 15 minutes.", dose: "1 à 2 tasses par jour, ou 500 mg d'extrait une à deux fois.", kids: "Pas d'usage médicinal.", caution: "Peut trop baisser la tension et la glycémie avec les médicaments." },
  sidr: { name: "Sidr (jujubier épine-du-Christ)", part: "Feuilles et fruits", uses: "Feuilles de sidr moulues en shampoing et lavage du corps, contre les pellicules, nettoyant de la peau. Le fruit (nabq) est un aliment légèrement laxatif.", prep: "Mélanger la poudre de feuilles à l'eau jusqu'à ce qu'elle mousse et laver les cheveux.", dose: "Usage externe.", kids: "Lavage généralement sans danger.", caution: "Peut assécher les cheveux." },
  marshmallow: { name: "Guimauve (racine)", part: "Racine et feuilles", uses: "Toux sèche et irritation de la gorge, gastrite légère (mucilage adoucissant).", prep: "Macération à froid : 2 à 5 g de racine dans une tasse d'eau froide 2 heures, puis filtrer.", dose: "3 tasses par jour.", kids: "Sirop standardisé pour enfants après 3 ans.", caution: "À prendre 1 heure à distance des médicaments (réduit l'absorption). Peut baisser la glycémie." },
  rose: { name: "Rose de Damas (eau de rose)", part: "Pétales et eau de rose", uses: "Apaise la peau, règles douloureuses (tisane de pétales), anxiété légère, constipation légère (confiture de rose).", prep: "Tisane : 1 cuillère à soupe de pétales secs dans une tasse d'eau bouillante. Eau de rose pour la peau.", dose: "1 à 3 tasses par jour.", kids: "Sans danger en quantité alimentaire.", caution: "Ne pas mettre d'eau de rose du commerce dans les yeux sauf si elle est stérile et prévue pour cet usage." },
  guava_leaf: { name: "Feuille de goyavier", part: "Feuilles", uses: "Diarrhée légère, aide la glycémie après les repas, inflammation des gencives (bain de bouche).", prep: "Faire bouillir 3 à 5 feuilles fraîches dans une tasse d'eau 10 minutes.", dose: "1 à 3 tasses par jour.", kids: "Sur avis.", caution: "Peut baisser la glycémie. Peut constiper." },
  pumpkin_seed: { name: "Graines de courge", part: "Graines", uses: "Symptômes de l'hypertrophie bénigne de la prostate et de la vessie hyperactive, vers traditionnellement, source de zinc.", prep: "Consommer crues ou légèrement grillées, ou utiliser l'huile.", dose: "10 g de graines par jour.", kids: "Quantités alimentaires.", caution: "Généralement sans danger." },
  harmal: { name: "Harmel (rue de Syrie) ⚠️", part: "Graines", uses: "Utilisé en pratique populaire en fumigation, pour avorter et « guérir » de nombreux maux. ⚠️ Plante toxique.", prep: "Aucun usage interne n'est conseillé.", dose: "Aucune dose sûre en automédication.", kids: "⛔ Interdit.", caution: "⛔ Intoxication grave : hallucinations, vomissements, tremblements, paralysie, défaillance cardiaque, fausse couche, parfois décès. Interaction dangereuse avec les antidépresseurs. L'une des intoxications végétales les plus fréquentes au Maghreb." },
  pennyroyal: { name: "Menthe pouliot (fliyou) ⚠️", part: "Feuilles", uses: "Utilisée en médecine populaire contre le rhume et la toux dans l'atay. ⚠️ Son huile est extrêmement toxique.", prep: "Si elle est utilisée, seulement quelques feuilles dans le thé, pour l'adulte.", dose: "Huile : aucune dose sûre.", kids: "⛔ Interdite chez l'enfant et le bébé (insuffisance hépatique mortelle).", caution: "⛔ L'huile de pouliot provoque une insuffisance du foie et des reins et la mort même en petite quantité. Utilisée pour avorter, avec des issues fatales. Strictement interdite pendant la grossesse." },
  oleander: { name: "Laurier-rose (defla) ⚠️", part: "Toutes les parties", uses: "⛔ Plante ornementale très toxique — ne jamais l'utiliser malgré les recettes populaires contre le diabète et pour la peau.", prep: "Ne pas utiliser.", dose: "Une très petite quantité peut être mortelle.", kids: "⛔ Mortel.", caution: "⛔ Contient des glycosides cardiaques provoquant des troubles du rythme mortels. En cas d'ingestion : appelez immédiatement les secours ou le centre antipoison." },
  datura: { name: "Datura (stramoine) ⚠️", part: "Toutes les parties", uses: "⛔ Autrefois fumé contre l'asthme — très toxique.", prep: "Ne pas utiliser.", dose: "Aucune dose sûre.", kids: "⛔ Interdit.", caution: "⛔ Provoque délire, hallucinations, pupilles dilatées, cœur rapide, fièvre, coma et décès." },
  oregano: { name: "Origan", part: "Feuilles et sommités fleuries", uses: "Toux et rhume, indigestion et gaz, antimicrobien, parasites intestinaux traditionnellement.", prep: "1 cuillère à café (1 à 2 g) dans une tasse d'eau bouillante 10 minutes.", dose: "2 à 3 tasses par jour. Huile d'origan par voie interne uniquement en gélules diluées et brièvement.", kids: "Quantités alimentaires seulement. Huile interdite chez l'enfant.", caution: "Allergie aux Lamiacées. L'huile concentrée irrite la bouche et l'estomac. Peut réduire l'absorption du fer et fluidifier le sang." },
  coriander: { name: "Coriandre", part: "Graines et feuilles", uses: "Gaz, ballonnements et indigestion, côlon irritable, appétit, aide à baisser la glycémie.", prep: "1 à 2 g de graines écrasées dans une tasse d'eau bouillante 10 minutes. Ayurveda : avec cumin et fenouil (tisane CCF).", dose: "2 à 3 tasses par jour.", kids: "Quantités alimentaires.", caution: "Allergie rare. Peut légèrement baisser la glycémie." },
  parsley: { name: "Persil", part: "Feuilles et racines", uses: "Diurétique, utilisé en médecine populaire pour les petits calculs rénaux et la rétention d'eau, mauvaise haleine ; riche en vitamines C et K.", prep: "Une poignée de feuilles fraîches (environ 2 g sec) bouillie dans une tasse d'eau 5 à 10 minutes.", dose: "1 à 3 tasses par jour sur une courte durée.", kids: "Quantités alimentaires.", caution: "⚠️ Les graines et l'huile (apiol) sont toxiques pour les reins et le foie et abortives. Éviter l'usage médicinal en cas de maladie rénale. Riche en vitamine K (interagit avec la warfarine)." },
  corn_silk: { name: "Barbe de maïs (stigmates)", part: "Filaments de l'épi", uses: "Diurétique doux, cystite légère (en complément), petits calculs rénaux traditionnellement.", prep: "1 cuillère à soupe (4 à 8 g) dans une tasse d'eau bouillante 10 à 15 minutes.", dose: "2 à 3 tasses par jour.", kids: "Sur avis.", caution: "Interagit avec les diurétiques, le lithium, les antihypertenseurs et les antidiabétiques. Peut baisser le potassium." },
  horsetail: { name: "Prêle des champs", part: "Tiges sèches", uses: "Diurétique, rétention d'eau, ongles et cheveux fragiles (riche en silice) traditionnellement.", prep: "2 à 4 g dans une tasse d'eau bouillante.", dose: "2 à 3 tasses par jour pendant 4 à 6 semaines maximum.", kids: "Non utilisée.", caution: "Fait perdre du potassium et de la thiamine (B1). Interdite en cas de maladie cardiaque ou rénale, de goutte et avec les diurétiques. Ne pas confondre avec la prêle des marais, toxique." },
  lemon_verbena: { name: "Verveine citronnelle (louiza)", part: "Feuilles", uses: "Indigestion et gaz, anxiété et insomnie légères, boisson apaisante après le dîner.", prep: "1 cuillère à café de feuilles (1 à 2 g) dans une tasse d'eau bouillante 5 à 10 minutes, ou avec l'atay.", dose: "2 à 3 tasses par jour.", kids: "Tisane légère après 4 ans.", caution: "De très grandes quantités peuvent irriter les reins. Sans danger en quantité de tisane." },
  linden: { name: "Tilleul", part: "Fleurs avec bractées", uses: "Rhume et toux sèche (favorise la transpiration), anxiété et insomnie légères.", prep: "1,5 g (1 cuillère à café) dans une tasse d'eau bouillante 5 à 10 minutes.", dose: "2 à 4 tasses par jour.", kids: "Tisane diluée après 4 ans.", caution: "Généralement sans danger. Allergie rare." },
  passionflower: { name: "Passiflore", part: "Parties aériennes", uses: "Anxiété et tension nerveuse, insomnie légère.", prep: "1 à 2 g dans une tasse d'eau bouillante 10 minutes, ou extrait.", dose: "Tisane 2 à 3 fois par jour, ou extrait selon le produit.", kids: "Pas avant 12 ans sans avis.", caution: "Renforce l'effet des sédatifs, des somnifères et de l'alcool. Peut provoquer une somnolence." },
  hawthorn: { name: "Aubépine", part: "Feuilles, fleurs et baies", uses: "Soutien cardiaque dans l'insuffisance cardiaque légère (en complément), palpitations nerveuses, hypertension légère.", prep: "Extrait standardisé ou 1 à 1,5 g dans une tasse d'eau bouillante.", dose: "Extrait 160 à 900 mg par jour en plusieurs prises.", kids: "Non utilisée.", caution: "⚠️ Interagit avec les médicaments du cœur (digoxine, bêtabloquants, dérivés nitrés) et les antihypertenseurs. Chez le cardiaque, seulement avec l'accord du médecin." },
  artichoke: { name: "Artichaut (feuille)", part: "Feuilles", uses: "Indigestion et ballonnements après les repas gras, stimule la bile, aide à baisser le cholestérol.", prep: "Extrait de feuille, ou 1 à 2 g dans une tasse d'eau bouillante (amer).", dose: "Jusqu'à 6 g de feuille sèche par jour, ou extrait selon le produit.", kids: "En aliment uniquement.", caution: "Interdit en cas d'obstruction des voies biliaires et de gros calculs. Allergie aux Astéracées." },
  horse_chestnut: { name: "Marronnier d'Inde", part: "Extrait standardisé des graines", uses: "Insuffisance veineuse chronique et varices : lourdeur, gonflement et douleur (bonnes preuves).", prep: "Uniquement en extrait standardisé (les graines crues sont toxiques).", dose: "300 mg d'extrait (50 mg d'escine) deux fois par jour.", kids: "Non utilisé.", caution: "⚠️ Graines, feuilles et écorce crues toxiques. Interagit avec les anticoagulants. À éviter en cas de maladie du foie ou des reins." },
  feverfew: { name: "Grande camomille (partenelle)", part: "Feuilles", uses: "Prévention des crises de migraine (preuves modérées).", prep: "Feuilles sèches en gélules.", dose: "50 à 150 mg de feuille sèche par jour pendant 3 à 4 mois pour évaluer.", kids: "Non utilisée.", caution: "Fluidifie le sang. Mâcher les feuilles fraîches provoque des aphtes. L'arrêt brutal peut causer un mal de tête de rebond. Allergie aux Astéracées." },
  ivy_leaf: { name: "Lierre grimpant (feuille)", part: "Extrait de feuille", uses: "Toux grasse et bronchite (sirop standardisé courant en Europe).", prep: "Uniquement sirop ou comprimés standardisés.", dose: "Selon la notice.", kids: "Sirop standardisé pour enfants selon l'âge ; pas avant 2 ans.", caution: "⚠️ Les feuilles et baies crues sont toxiques. Peut causer nausées et diarrhée." },
  uva_ursi: { name: "Busserole (raisin d'ours)", part: "Feuilles", uses: "Cystite légère non compliquée chez la femme adulte (antiseptique urinaire).", prep: "Macération à froid : 3 g dans 150 ml d'eau froide plusieurs heures.", dose: "Jusqu'à 3 à 4 fois par jour, pas plus d'une semaine et pas plus de 5 fois par an.", kids: "⛔ Pas avant 12 ans.", caution: "⚠️ L'usage prolongé nuit au foie. Interdite en cas de maladie rénale. Colore les urines en brun-vert. Ne pas associer aux acidifiants urinaires." },
  evening_primrose: { name: "Onagre", part: "Huile des graines (capsules)", uses: "Douleurs cycliques des seins, eczéma (preuves faibles), syndrome prémenstruel.", prep: "Capsules d'huile.", dose: "1 à 3 g par jour.", kids: "Sur avis.", caution: "Fluidifie le sang. Prudence en cas d'épilepsie et avec les phénothiazines." },
  bitter_melon: { name: "Margose (melon amer, karela)", part: "Fruit", uses: "Aide à baisser la glycémie (preuves modestes) ; aliment traditionnel en Asie.", prep: "Cuire le fruit ou boire de petites quantités de son jus.", dose: "En aliment, ou extrait selon le produit.", kids: "⛔ Les graines et l'arille rouge sont toxiques pour l'enfant.", caution: "⚠️ Hypoglycémie avec les antidiabétiques. Les graines provoquent une hémolyse en cas de déficit en G6PD (favisme). Stimule l'utérus." },
  gymnema: { name: "Gymnema (gurmar, « destructeur de sucre »)", part: "Feuilles", uses: "Aide au contrôle de la glycémie et réduit l'envie de sucré (bloque temporairement le goût sucré).", prep: "Extrait standardisé.", dose: "200 à 400 mg d'extrait par jour.", kids: "Non utilisé.", caution: "⚠️ Hypoglycémie avec l'insuline et les antidiabétiques. Rares atteintes du foie." },
  amla: { name: "Amla (groseille indienne)", part: "Fruit", uses: "Très riche en vitamine C, soutien immunitaire, cheveux (huile d'amla), digestion ; l'un des fruits du triphala.", prep: "Poudre dans de l'eau ou du miel, ou fruit frais ou confit.", dose: "1 à 3 g de poudre par jour.", kids: "Quantités alimentaires.", caution: "Peut légèrement fluidifier le sang et baisser la glycémie." },
  mastic: { name: "Mastic (gomme de lentisque)", part: "Résine", uses: "Indigestion et ulcère de l'estomac, H. pylori (premières études en complément), mauvaise haleine et inflammation des gencives (à mâcher).", prep: "À mâcher, ou moudre et prendre avec de l'eau, ou en gélules.", dose: "1 à 2 g par jour en plusieurs prises.", kids: "Mâcher un petit morceau.", caution: "Allergie chez les personnes allergiques à la pistache. Généralement sans danger." },
  carob: { name: "Caroube", part: "Gousses", uses: "Diarrhée de l'enfant (la poudre de caroube épaissit les selles), substitut du cacao sans caféine, constipation (sirop sucré).", prep: "Poudre dans les aliments, ou boisson de caroube macérée.", dose: "Diarrhée : 15 g de poudre par jour chez l'adulte.", kids: "1 à 2 cuillères à café de poudre dans les aliments après 1 an.", caution: "Généralement sans danger. Peut réduire l'absorption de certains minéraux." },
  caraway: { name: "Carvi", part: "Graines", uses: "Gaz, ballonnements et coliques, indigestion (associé à l'huile de menthe poivrée — bonnes preuves) ; cuisiné pour les jeunes mamans au Levant.", prep: "1 à 2 g de graines écrasées dans une tasse d'eau bouillante 10 minutes.", dose: "2 à 3 tasses par jour.", kids: "Tisane diluée après 2 ans.", caution: "Sans danger en quantité alimentaire." },
  dill: { name: "Aneth", part: "Graines et feuilles", uses: "Gaz et coliques, hoquet, production de lait traditionnellement.", prep: "1 à 3 g de graines écrasées dans une tasse d'eau bouillante.", dose: "2 à 3 tasses par jour.", kids: "Tisane diluée après 2 ans.", caution: "Allergie chez les personnes allergiques à la carotte et au céleri. Peut provoquer une photosensibilité." },
  lemongrass: { name: "Citronnelle", part: "Feuilles et tiges", uses: "Indigestion, anxiété légère, fièvre et rhume traditionnellement, répulsif à insectes (huile).", prep: "1 cuillère à café dans une tasse d'eau bouillante 5 à 10 minutes.", dose: "2 à 3 tasses par jour.", kids: "Tisane légère.", caution: "L'huile irrite la peau. Sans danger en quantité de tisane." },
  rooibos: { name: "Rooibos (thé rouge africain)", part: "Feuilles", uses: "Boisson sans caféine riche en antioxydants ; substitut du thé pour enfants, femmes enceintes et insomniaques ; coliques traditionnellement.", prep: "1 cuillère à café dans une tasse d'eau bouillante 5 minutes.", dose: "Jusqu'à 4 à 6 tasses par jour.", kids: "Adapté, dilué.", caution: "Très rares cas d'élévation des enzymes du foie." },
  maca: { name: "Maca (ginseng péruvien)", part: "Racine", uses: "Énergie et fatigue, libido, symptômes de la ménopause (preuves limitées).", prep: "Poudre de racine cuite dans un jus ou un aliment.", dose: "1,5 à 3 g par jour.", kids: "Non utilisée.", caution: "Contient des substances pouvant agir sur la thyroïde — de préférence cuite. Prudence en cas de troubles hormonaux." },
  cats_claw: { name: "Griffe de chat (uña de gato)", part: "Écorce et racine", uses: "Douleurs articulaires et arthrose (preuves limitées), soutien immunitaire dans la tradition amazonienne.", prep: "Décoction d'écorce ou extrait.", dose: "250 à 350 mg d'extrait par jour.", kids: "Non utilisée.", caution: "À éviter en cas de maladie auto-immune, avec les immunosuppresseurs, les anticoagulants et avant une chirurgie." },
  reishi: { name: "Reishi (ganoderme, lingzhi)", part: "Champignon", uses: "Soutien immunitaire, fatigue et sommeil traditionnellement (preuves humaines faibles).", prep: "Décoction de tranches de champignon, ou extrait.", dose: "1,5 à 9 g de champignon sec par jour, ou extrait selon le produit.", kids: "Non utilisé.", caution: "Rares atteintes du foie avec la poudre. Fluidifie le sang et baisse la tension et la glycémie. Arrêter avant une chirurgie." },
  gotu_kola: { name: "Centella (gotu kola)", part: "Feuilles", uses: "Insuffisance veineuse et varices, cicatrisation et cicatrices (crèmes), mémoire traditionnellement.", prep: "Tisane de feuilles, extrait ou crème.", dose: "Extrait 60 à 120 mg par jour pendant 6 semaines maximum, puis 2 semaines de pause.", kids: "En application uniquement.", caution: "Rares atteintes du foie. Peut provoquer une somnolence." },
  bacopa: { name: "Bacopa (brahmi)", part: "Plante entière", uses: "Mémoire et apprentissage (preuves modérées après 12 semaines), anxiété.", prep: "Extrait standardisé, ou poudre avec du ghee ou du lait en ayurveda.", dose: "300 mg d'extrait par jour avec un repas.", kids: "Sur avis.", caution: "Troubles digestifs. Peut ralentir le cœur et agir sur la thyroïde." },
  shatavari: { name: "Shatavari (asperge indienne)", part: "Racine", uses: "Tonique féminin en ayurveda : production de lait, symptômes de la ménopause, acidité traditionnellement.", prep: "Poudre dans du lait chaud.", dose: "1 à 3 g de poudre par jour.", kids: "Non utilisée.", caution: "Allergie à l'asperge. Légèrement diurétique." },
  andrographis: { name: "Andrographis (roi des amers)", part: "Feuilles", uses: "Soulage le rhume et le mal de gorge s'il est pris tôt (preuves modérées).", prep: "Extrait standardisé.", dose: "300 à 400 mg d'extrait 3 fois par jour pendant 5 à 7 jours.", kids: "Sur avis.", caution: "Allergie parfois grave. Peut baisser la tension et fluidifier le sang. À éviter en cas de projet de grossesse." },
  slippery_elm: { name: "Orme rouge (slippery elm)", part: "Écorce interne", uses: "Mal de gorge et toux, brûlures d'estomac et reflux (forme un film apaisant).", prep: "1 à 2 cuillères à café de poudre dans une tasse d'eau tiède.", dose: "3 fois par jour.", kids: "Pastilles après 6 ans.", caution: "À prendre 2 heures à distance des médicaments. L'écorce externe peut provoquer une fausse couche." },
  witch_hazel: { name: "Hamamélis", part: "Feuilles et écorce (eau distillée)", uses: "En externe : hémorroïdes, bleus, piqûres d'insectes, peau grasse, petites inflammations de la peau.", prep: "Eau d'hamamélis ou pommade appliquée avec du coton.", dose: "En application jusqu'à 6 fois par jour.", kids: "En application généralement sans danger.", caution: "Usage externe uniquement." },
  arnica: { name: "Arnica", part: "Fleurs (gel/pommade)", uses: "En externe : bleus, entorses et courbatures après l'effort.", prep: "Gel ou pommade prêts à l'emploi.", dose: "En application 2 à 3 fois par jour.", kids: "En application après 6 ans, sur peau intacte.", caution: "⛔ Toxique si avalée. Jamais sur une plaie ouverte. Allergie aux Astéracées." },
  henna: { name: "Henné", part: "Feuilles moulues", uses: "Teindre et fortifier les cheveux et rafraîchir le cuir chevelu, talons crevassés, traditionnellement sur la tête contre les maux de tête et sur les plaies.", prep: "Mélanger la poudre à de l'eau tiède ou du thé, laisser reposer 2 heures puis appliquer.", dose: "Usage externe uniquement.", kids: "⛔ Ne pas appliquer sur les bébés et jeunes enfants (risque d'hémolyse en cas de déficit en G6PD).", caution: "⚠️ Le « henné noir » contient de la PPD, qui provoque des brûlures et une allergie cutanée permanente — n'utilisez que du henné naturel. Ne pas avaler." },
  bay_leaf: { name: "Laurier (sauce)", part: "Feuilles", uses: "Indigestion et gaz, cuisine ; l'huile en application pour les douleurs articulaires et les pellicules.", prep: "Faire bouillir 1 à 2 feuilles dans une tasse d'eau 5 minutes.", dose: "1 à 2 tasses par jour.", kids: "Quantités alimentaires (retirer les feuilles entières — risque d'étouffement).", caution: "Peut baisser la glycémie. Arrêter avant une chirurgie (effet sédatif)." },
  pomegranate_peel: { name: "Écorce de grenade", part: "Écorce séchée du fruit", uses: "Diarrhée traditionnellement (astringente), inflammation des gencives et de la gorge (gargarisme), vers traditionnellement.", prep: "Faire bouillir 2 à 3 g d'écorce sèche dans une tasse d'eau 10 minutes.", dose: "1 à 2 tasses par jour pendant 2 à 3 jours.", kids: "Pas chez l'enfant (alcaloïdes toxiques à forte dose).", caution: "De fortes doses d'écorce et de racine sont toxiques. Peut interagir avec certains médicaments. Les grains et le jus sont un aliment sans danger." },
  rue: { name: "Rue (fijel) ⚠️", part: "Feuilles", uses: "Utilisée en médecine populaire contre les coliques, le retard de règles, le « mauvais œil » et pour avorter. ⚠️ Plante toxique.", prep: "Aucun usage interne n'est conseillé.", dose: "Aucune dose sûre en automédication.", kids: "⛔ Interdite.", caution: "⛔ Provoque des saignements utérins et des fausses couches pouvant tuer la mère, ainsi que des atteintes du foie et des reins. La toucher puis s'exposer au soleil provoque des brûlures avec cloques." },
  colocynth: { name: "Coloquinte (hdaja) ⚠️", part: "Fruit", uses: "Utilisée en médecine populaire contre le diabète et les rhumatismes (frottée ou piétinée) et comme purgatif violent. ⚠️ Toxique.", prep: "Aucun usage interne.", dose: "Aucune dose sûre.", kids: "⛔ Interdite.", caution: "⛔ Provoque colite hémorragique, diarrhée sanglante sévère, déshydratation et insuffisance rénale ; des décès sont rapportés. Même l'application sur la peau peut être absorbée." }
};
